import {required,faultModes,sampleTimes} from './workshop-model.mjs';
import {causes,repairScore} from './workshop-repair-model.mjs';
export const repairHistoryKey='mecanica.workshop.repairHistory.v1';
export const repairDraftKey='mecanica.workshop.repairDrafts.v1';
export function validRepair(r){return Boolean(r&&typeof r.id==='string'&&r.id.length<150&&Object.hasOwn(required,r.kind)&&faultModes.includes(r.fault)&&Array.isArray(r.fixed)&&r.fixed.every(x=>causes(r).includes(x))&&new Set(r.fixed).size===r.fixed.length&&Array.isArray(r.actions)&&r.actions.every(a=>a&&['primary','alternate'].includes(a.id)&&typeof a.useful==='boolean')&&Array.isArray(r.readings)&&r.readings.every(x=>x&&required[r.kind].includes(x.id)&&sampleTimes(r).includes(x.time))&&Number.isInteger(r.hints)&&r.hints>=0&&Number.isInteger(r.failedChecks)&&r.failedChecks>=0&&typeof r.verified==='boolean'&&(!r.verified||(causes(r).every(x=>r.fixed.includes(x))&&required[r.kind].every(id=>sampleTimes(r).every(time=>r.readings.some(x=>x.id===id&&x.time===time))))));}
export function loadRepairHistory(storage){const data=JSON.parse(storage.getItem(repairHistoryKey)||'[]');return Array.isArray(data)?data.filter(r=>validRepair(r)&&r.verified&&Number.isFinite(Date.parse(r.finished))).filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished)).slice(-100):[];}
export function archiveRepair(storage,r){if(!validRepair(r)||!r.verified)return false;const rows=loadRepairHistory(storage);if(rows.some(x=>x.id===r.id))return true;storage.setItem(repairHistoryKey,JSON.stringify([...rows,{...r,finished:r.finished||new Date().toISOString(),score:repairScore(r)}].slice(-100)));return true;}
export function repairStrengths(rows){const groups=new Map();for(const r of rows){const key=r.kind+':'+r.fault;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return [...groups].map(([key,rs])=>{const recent=rs.slice(-3),mean=Math.round(recent.reduce((s,r)=>s+repairScore(r),0)/recent.length);return {key,kind:rs[0].kind,fault:rs[0].fault,count:rs.length,first:repairScore(rs[0]),latest:repairScore(rs.at(-1)),mean,hints:recent.reduce((s,r)=>s+r.hints,0),unnecessary:recent.reduce((s,r)=>s+r.actions.filter(a=>!a.useful).length,0),failedChecks:recent.reduce((s,r)=>s+r.failedChecks,0),priority:100-mean};}).sort((a,b)=>b.priority-a.priority||a.count-b.count||a.key.localeCompare(b.key));}
